import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import extractText from 'flarum/common/utils/extractText';
import RoomTile from './RoomTile';
const t = (key, params) => app.translator.trans('ernestdefoe-parley.forum.rooms.' + key, params);

/** One room in the rail: its tile, its name, who is in there now. */
export default class RoomRow extends Component {
  view() {
    const r = this.attrs.room;
    const open = () => app.parley.openRoom(r.id);
    return m("div", {
      className: 'pl-person pl-room' + (r.joined ? ' joined' : ''),
      tabindex: "0",
      role: "button",
      "aria-label": extractText(t('open', {
        name: r.name
      })),
      onclick: open,
      onkeydown: e => {
        if ((e.key === 'Enter' || e.key === ' ') && e.target === e.currentTarget) {
          e.preventDefault();
          open();
        }
      }
    }, RoomTile(r, 36), m("div", {
      className: "pl-info"
    }, m("div", {
      className: "pl-nm"
    }, r.name, r.readonly ? m("span", {
      className: "pl-badge"
    }, t('announcements')) : null), m("div", {
      className: "pl-act"
    }, r.online ? [m("i", {
      className: "pl-live-dot"
    }), t('online_count', {
      count: r.online
    }), r.description ? ' · ' : ''] : null, r.description || (r.online ? null : t('members_count', {
      count: r.members
    })))), r.unread ? m("span", {
      className: "pl-unread"
    }, r.unread > 99 ? '99+' : r.unread) : null);
  }
}
flarum.reg.add('ernestdefoe-parley', 'forum/components/RoomRow', RoomRow);